	"player_id" uuid PRIMARY KEY NOT NULL,
	"day" integer DEFAULT 1 NOT NULL,
	"claimed_days" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"last_day_key" text,
	"finished_at" timestamp with time zone
);
