-- Data (spec G): `streak` now counts the month's claims and forgives a missed day, so a count broken this month is
-- lifted to `claimed_days`. Only rows of the current month in the economy's default zone; a second run matches none.
UPDATE "daily_logins" SET "streak" = "claimed_days"
WHERE "streak" < "claimed_days" AND "month" = to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM');
